    public function fetch_markets($params = array()): array {
        /**
         * retrieves data on all markets for nobitex
         *
         * @see https://apidocs.nobitex.ir
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} an array of objects representing market data
         */
        $response = $this->publicGetV2Options($params);
        //
        //     {
        //         "status": "ok",
        //         "nobitex": {
        //             "amountPrecisions": { "BTCIRT": "0.000001", "BTCUSDT": "0.000001", ... },
        //             "pricePrecisions": { "BTCIRT": "10", "BTCUSDT": "0.01", ... },
        //             "minOrders": { "rls": "500000", "usdt": "0.5", ... },
        //         }
        //     }
        //
        // ponytail: there is no dedicated markets endpoint, the precision maps are the market list
        $options = $this->safe_dict($response, 'nobitex', array());
        $amountPrecisions = $this->safe_dict($options, 'amountPrecisions', array());
        $ids = is_array($amountPrecisions) ? array_keys($amountPrecisions) : array();
        $pricePrecisions = $this->safe_dict($options, 'pricePrecisions', array());
        $minOrders = $this->safe_dict($options, 'minOrders', array());
        $quoteIds = $this->safe_dict($this->options, 'quoteIds', array());
        $suffixes = is_array($quoteIds) ? array_keys($quoteIds) : array();
        $result = array();
        for ($i = 0; $i < count($ids); $i++) {
            $id = $ids[$i];
            for ($j = 0; $j < count($suffixes); $j++) {
                if (str_ends_with($id, $suffixes[$j])) {
                    $quoteId = $this->safe_string($quoteIds, $suffixes[$j]);
                    $result[] = $this->parse_market(array(
                        'id' => $id,
                        'baseId' => strtolower(mb_substr($id, 0, strlen($id) - strlen($suffixes[$j]) - 0)),
                        'quoteId' => $quoteId,
                        'amountPrecision' => $this->safe_string($amountPrecisions, $id),
                        'pricePrecision' => $this->safe_string($pricePrecisions, $id),
                        'minOrder' => $this->safe_string($minOrders, $quoteId),
                    ));
                    break;
                }
            }
        }
        return $result;
    }

    public function parse_market(array $market): array {
        $id = $this->safe_string($market, 'id');
        //
        //     { "id": "BTCIRT", "baseId": "btc", "quoteId": "rls", "amountPrecision": "0.000001", "pricePrecision": "10", "minOrder": "500000" }
        //
        $baseId = $this->safe_string($market, 'baseId');
        $quoteId = $this->safe_string($market, 'quoteId');
        $base = $this->safe_currency_code($baseId);
        // prices on IRT markets are quoted in rials, not tomans
        $quoteCode = ($quoteId === 'rls') ? 'IRR' : $this->safe_currency_code($quoteId);
        return $this->safe_market_structure(array(
            'id' => $id,
            'symbol' => $base . '/' . $quoteCode,
            'base' => $base,
            'quote' => $quoteCode,
            'baseId' => $baseId,
            'quoteId' => $quoteId,
            'type' => 'spot',
            'spot' => true,
            'margin' => false,
            'swap' => false,
            'future' => false,
            'option' => false,
            'active' => true,
            'contract' => false,
            'precision' => array(
                'amount' => $this->safe_number($market, 'amountPrecision'),
                'price' => $this->safe_number($market, 'pricePrecision'),
            ),
            'limits' => array(
                'amount' => array( 'min' => null, 'max' => null ),
                'price' => array( 'min' => null, 'max' => null ),
                'cost' => array( 'min' => $this->safe_number($market, 'minOrder'), 'max' => null ),
                'leverage' => array( 'min' => null, 'max' => null ),
            ),
            'created' => null,
            'info' => $market,
        ));
    }

    public function fetch_ticker(string $symbol, $params = array()): array {
        /**
         * fetches a price $ticker, a statistical calculation with the information calculated over the past 24 hours for a specific $market
         *
