    public function fetch_order_book(string $symbol, ?int $limit = null, $params = array()): array {
        /**
         * fetches information on open orders with bid (buy) and ask (sell) prices, volumes and other data
         *
         * @see https://apidocs.nobitex.ir
         *
         * @param {string} $symbol unified $symbol of the $market to fetch the order book for
         * @param {int} [$limit] the maximum amount of order book entries to return
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} A dictionary of ~@link https://docs.ccxt.com/?id=order-book-structure order book structures~ indexed by $market symbols
         */
        $this->load_markets();
        $market = $this->market($symbol);
        $request = array(
            'symbol' => $market['id'],
        );
        $response = $this->publicGetV3OrderbookSymbol($this->extend($request, $params));
        //
        //     {
        //         "status": "ok",
        //         "lastUpdate": 1790163055765,
        //         "lastTradePrice": "85500",
        //         "bids": [ [ "85405", "0.002623" ], ... ],
        //         "asks": [ [ "85500", "0.1" ], ... ]
        //     }
        //
        // ponytail: base parseOrderBook already handles [price, amount] string pairs
        $orderbook = $this->parse_order_book($response, $market['symbol'], $this->safe_integer($response, 'lastUpdate'));
        if ($limit !== null) {
            $orderbook['bids'] = $this->array_slice($orderbook['bids'], 0, $limit);
            $orderbook['asks'] = $this->array_slice($orderbook['asks'], 0, $limit);
        }
        return $orderbook;
    }

    public function create_order(string $symbol, string $type, string $side, float $amount, ?float $price = null, $params = array()): array {
        /**
         * create a trade $order
         *
         * @see https://apidocs.nobitex.ir/spot_trade/api-%D9%85%D8%B9%D8%A7%D9%85%D9%84%D8%A7%D8%AA-%D8%A7%D8%B3%D9%BE%D8%A7%D8%AA-%D9%86%D9%88%D8%A8%DB%8C%D8%AA%DA%A9%D8%B3
         *
         * @param {string} $symbol unified $symbol of the $market to create an $order in
         * @param {string} $type 'market' or 'limit'
         * @param {string} $side 'buy' or 'sell'
         * @param {float} $amount how much of the base currency you want to trade
         * @param {float} [$price] required for limit orders, optional for $market orders where it caps the execution $price
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {float} [$params->triggerPrice] turns the $order into stop_limit or stop_market
         * @param {string} [$params->clientOrderId] up to 32 chars of [A-Za-z0-9-], unique among open orders
         * @return {array} an ~@link https://docs.ccxt.com/?id=$order-structure $order structure~
         */
        $this->load_markets();
        $market = $this->market($symbol);
        $request = array(
            'srcCurrency' => $market['baseId'],
            'dstCurrency' => $market['quoteId'],
            'type' => $side,
            'execution' => $type,
            'amount' => $this->amount_to_precision($symbol, $amount),
        );
        $triggerPrice = $this->safe_string_2($params, 'triggerPrice', 'stopPrice');
        if ($triggerPrice !== null) {
            $request['execution'] = 'stop_' . $type;
            $request['stopPrice'] = $this->price_to_precision($symbol, $triggerPrice);
        }
        if ($price !== null) {
            $request['price'] = $this->price_to_precision($symbol, $price);
        }
        $clientOrderId = $this->safe_string($params, 'clientOrderId');
        if ($clientOrderId !== null) {
            $request['clientOrderId'] = $clientOrderId;
        }
        $params = $this->omit($params, array( 'triggerPrice', 'stopPrice', 'clientOrderId' ));
        $response = $this->privatePostMarketOrdersAdd($this->extend($request, $params));
        //
        //     {
        //         "status": "ok",
        //         "order": {
        //             "id": 25, "clientOrderId": "order1", "type": "buy", "execution": "Limit", "tradeType": "Spot",
        //             "market": "BTC-RLS", "srcCurrency": "Bitcoin", "dstCurrency": "﷼", "status": "Active", "partial": false,
        //             "amount": "0.6", "price": "520000000", "averagePrice": "0", "matchedAmount": "0", "unmatchedAmount": "0.6",
        //             "totalPrice": "0", "totalOrderPrice": "312000000", "fee": "0", "created_at": "2018-11-28T11:36:13.592827+00:00"
        //         }
        //     }
        //
        $order = $this->safe_dict($response, 'order', array());
        return $this->parse_order($order, $market);
    }

    public function parse_order(array $order, ?array $market = null): array {
        // "BTC-RLS" -> "BTCIRT", "BTC-USDT" -> "BTCUSDT"
        $marketId = $this->safe_string($order, 'market');
        if ($marketId !== null) {
            $marketId = str_replace('-RLS', 'IRT', $marketId);
            $marketId = str_replace('-', '', $marketId);
        }
        $market = $this->safe_market($marketId, $market);
        $execution = $this->safe_string($order, 'execution'); // Limit, Market, StopLimit, StopMarket
        $type = null;
        if ($execution !== null) {
            $type = str_ends_with($execution, 'Market') ? 'market' : 'limit';
        }
        $statuses = $this->safe_dict($this->options, 'orderStatuses', array());
        $average = $this->safe_string($order, 'averagePrice');
        return $this->safe_order(array(
            'id' => $this->safe_string($order, 'id'),
            'clientOrderId' => $this->safe_string($order, 'clientOrderId'),
            'timestamp' => $this->parse8601($this->safe_string($order, 'created_at')),
            'datetime' => null,
            'lastTradeTimestamp' => null,
            'symbol' => $market['symbol'],
            'type' => $type,
            'timeInForce' => null,
            'postOnly' => null,
            'side' => $this->safe_string($order, 'type'),
            'price' => $this->safe_string($order, 'price'),
            'triggerPrice' => $this->safe_string($order, 'param1'),
            'amount' => $this->safe_string($order, 'amount'),
            'filled' => $this->safe_string($order, 'matchedAmount'),
            'remaining' => $this->safe_string($order, 'unmatchedAmount'),
            'cost' => $this->safe_string($order, 'totalPrice'),
            'average' => ($average === '0') ? null : $average,
            'status' => $this->safe_string($statuses, $this->safe_string($order, 'status')),
            'fee' => array(
                'cost' => $this->safe_string($order, 'fee'),
                'currency' => null,
            ),
            'trades' => null,
            'info' => $order,
        ), $market);
    }

    public function sign(mixed $path, mixed $api = 'public', $method = 'GET', $params = array(), ?array $headers = null, ?string $body = null) {
        $fullPath = '/' . $this->implode_params($path, $params);
        $query = $this->omit($params, $this->extract_params($path));
        $headers = array();
        if ($method === 'POST') {
            $body = $this->json($query);
            $headers['Content-Type'] = 'application/json';
        } elseif (count($query) > 0) {
            $fullPath .= '?' . $this->urlencode($query);
        }
        if ($api === 'private') {
            $this->check_required_credentials();
            if ($this->secret !== null && $this->secret !== '') {
                // API Key auth: Ed25519 over timestamp + METHOD + full_path + raw_body, keys and signature are url-safe base64
                $timestamp = (string) $this->seconds();
                $payload = $timestamp . $method . $fullPath;
                if ($body !== null) {
                    $payload .= $body;
                }
                $secret = $this->secret;
                $secret = str_replace('-', '+', $secret);
                $secret = str_replace('_', '/', $secret);
                $seed = $this->array_slice(base64_decode($secret), 0, 32);
                $signature = $this->eddsa($this->encode($payload), $seed, 'ed25519');
                $signature = str_replace('+', '-', $signature);
                $signature = str_replace('/', '_', $signature);
                $headers['Nobitex-Key'] = $this->apiKey;
                $headers['Nobitex-Timestamp'] = $timestamp;
                $headers['Nobitex-Signature'] = $signature;
            } else {
                // legacy session token
                $headers['Authorization'] = 'Token ' . $this->apiKey;
            }
        }
        $url = $this->urls['api']['rest'] . $fullPath;
        return array( 'url' => $url, 'method' => $method, 'body' => $body, 'headers' => $headers );
    }

    public function handle_errors(int $httpCode, string $reason, string $url, string $method, array $headers, string $body, mixed $response, mixed $requestHeaders, mixed $requestBody) {
        if ($response === null) {
            return null;
        }
        //
        //     { "status": "failed", "code": "InvalidSymbol", "message": "..." }
        //     { "detail": "توکن غیر مجاز" } // invalid token, http 401
        //
        if ($httpCode === 401 || $httpCode === 403) {
            throw new AuthenticationError($this->id . ' ' . $body);
        }
        $status = $this->safe_string($response, 'status');
        if ($status !== null && $status !== 'ok') {
            throw new ExchangeError($this->id . ' ' . $body);
        }
        return null;
    }
